  function RequestField({name,value,onChange,ar,compact}){
    const def=FIELD_DEFS[name]||{l:[name,name]};const label=def.l[ar?1:0];
    if(def.kind==='expenses')return null;
    if(def.kind==='checkbox')return html`<div class="req3-field ${compact?'':'full'}"><label class="req3-check"><input type="checkbox" checked=${!!value} onChange=${e=>onChange(e.target.checked)}/><span>${label}</span></label></div>`;
    let input;
    if(def.kind==='textarea')input=html`<textarea class="sel" rows=${compact?2:4} value=${value||''} required=${!!def.required} onInput=${e=>onChange(e.target.value)}></textarea>`;
    else if(def.kind==='select')input=html`<select class="sel" value=${value||''} required=${!!def.required} onChange=${e=>onChange(e.target.value)}><option value="">—</option>${def.options.map(o=>html`<option key=${o[0]} value=${o[0]}>${o[ar?2:1]}</option>`)}</select>`;
    else input=html`<input class="sel" type=${def.kind||'text'} min=${def.kind==='number'?'0':null} step=${def.kind==='number'?'0.01':null} value=${value||''} required=${!!def.required} onInput=${e=>onChange(e.target.value)}/>`;
    return html`<div class="req3-field ${def.kind==='textarea'?'full':''}"><label>${label}${def.required?' *':''}</label>${input}</div>`;
  }

  function ExpenseLines({lines,setLines,ar}){
    const update=(i,k,v)=>setLines(lines.map((line,index)=>index===i?Object.assign({},line,{[k]:v}):line));
    const add=()=>setLines(lines.concat([{expenseDate:todayISO(),category:'',amount:'',currency:'EGP',clientOrProject:'',businessReason:''}]));
    const total=lines.reduce((sum,line)=>sum+(Number(line.amount)||0),0);
    return html`<div class="req3-field full"><label>${L(ar,'Expense lines','بنود المصروفات')} *</label>${lines.map((line,i)=>html`<div class="req3-expense" key=${i}><input class="sel" type="date" value=${line.expenseDate} onChange=${e=>update(i,'expenseDate',e.target.value)}/><input class="sel" placeholder=${L(ar,'Category','التصنيف')} value=${line.category} onInput=${e=>update(i,'category',e.target.value)}/><input class="sel" type="number" min="0" step="0.01" placeholder=${L(ar,'Amount','المبلغ')} value=${line.amount} onInput=${e=>update(i,'amount',e.target.value)}/><select class="sel" value=${line.currency} onChange=${e=>update(i,'currency',e.target.value)}><option>EGP</option><option>USD</option><option>EUR</option></select><input class="sel" placeholder=${L(ar,'Business reason / project','سبب المصروف / المشروع')} value=${line.businessReason} onInput=${e=>update(i,'businessReason',e.target.value)}/><button type="button" class="icon-btn" disabled=${lines.length===1} onClick=${()=>setLines(lines.filter((_,index)=>index!==i))}>×</button></div>`)}<div class="flex between center"><button type="button" class="mini" onClick=${add}>${h(Icon.plus)} ${L(ar,'Add line','إضافة بند')}</button><b class="mono">${total.toLocaleString()} EGP</b></div></div>`;
  }

  async function uploadRequestAttachment(ctx,policy,file,setProgress){
    if(!file)return null;if(file.size>DOCUMENT_MAX_BYTES)throw new Error('Maximum file size is 25 MB.');
    let slot=null;
    try{
      setProgress(8);const variants=await prepareDocumentVariants(file);setProgress(18);
      slot=await requestRpc(ctx,'create_employee_request_upload_v3',{p_organization_id:ctx.organizationId||tenantOrganizationId(),p_title:file.name.replace(/\.[^.]+$/,''),p_classification:policy.classification,p_original_filename:file.name,p_mime_type:file.type||'application/octet-stream',p_original_size_bytes:file.size,p_generate_variants:variants.generate});
      if(!slot||!slot.ok)throw new Error(slot&&slot.error||'upload_slot_failed');
      await storageUploadObject(ctx.cfg,slot.bucket,slot.originalPath,file);setProgress(56);
      if(variants.generate){await storageUploadObject(ctx.cfg,slot.bucket,slot.optimizedPath,variants.optimized);setProgress(74);await storageUploadObject(ctx.cfg,slot.bucket,slot.thumbnailPath,variants.thumbnail);setProgress(88);}
      const checksum=await documentSha256(file);const done=await requestRpc(ctx,'finalize_document_upload_v2',{p_organization_id:ctx.organizationId||tenantOrganizationId(),p_document_id:slot.id,p_checksum_sha256:checksum,p_optimized_size_bytes:variants.optimized&&variants.optimized.size||null,p_thumbnail_size_bytes:variants.thumbnail&&variants.thumbnail.size||null});
      if(!done||!done.ok)throw new Error(done&&done.error||'upload_finalize_failed');setProgress(100);return slot.id;
    }catch(error){if(slot&&slot.id)try{await requestRpc(ctx,'cancel_document_upload_v2',{p_organization_id:ctx.organizationId||tenantOrganizationId(),p_document_id:slot.id});}catch(ignore){}throw error;}
  }

